<template><PageShell title="Duty & Availability" subtitle="Monitor operational personnel and update who is available for assignment." icon="lucide:user-check" eyebrow="Organization Operations"><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Stat label="Members" :value="stats.members"/><Stat label="Available" :value="stats.available"/><Stat label="Assigned" :value="assignedCount"/><Stat label="Pending invites" :value="stats.pending_invites"/></div><section class="mt-6 overflow-hidden rounded-3xl border border-base-300 bg-base-100 shadow-sm dark:border-white/10 dark:bg-[#071829]"><div v-if="loading" class="py-20 text-center text-sm text-slate-400">Loading duty roster...</div><div v-else class="overflow-x-auto"><table class="w-full min-w-[900px] text-left text-sm"><thead class="bg-base-200/70 text-[.66rem] font-black uppercase text-slate-400"><tr><th class="px-5 py-3">Member</th><th class="px-5 py-3">Roles</th><th class="px-5 py-3">Membership</th><th class="px-5 py-3">Availability</th><th class="px-5 py-3">Action</th></tr></thead><tbody class="divide-y divide-base-300"><tr v-for="m in members" :key="m.id"><td class="px-5 py-4"><p class="font-black dark:text-white/75">{{ m.first_name }} {{ m.last_name }}</p><p class="text-xs text-slate-400">{{ m.employee_code||m.email }}</p></td><td class="px-5 py-4 text-xs font-bold text-slate-500">{{ m.role_names?.join(', ')||pretty(m.account_role) }}</td><td class="px-5 py-4"><span class="rounded-full bg-base-200 px-2.5 py-1 text-[.65rem] font-black">{{ pretty(m.membership_status) }}</span></td><td class="px-5 py-4"><span class="rounded-full px-2.5 py-1 text-[.65rem] font-black" :class="m.availability_status==='available'?'bg-emerald-100 text-emerald-700':m.availability_status==='assigned'?'bg-blue-100 text-blue-700':'bg-slate-200 text-slate-600'">{{ pretty(m.availability_status||'off_duty') }}</span></td><td class="px-5 py-4"><select v-if="canUpdate && m.account_role!=='organization_admin'" :value="m.availability_status" class="rounded-xl border border-base-300 bg-base-100 px-3 py-2 text-xs font-bold dark:bg-white/5 dark:text-white" @change="change(m,$event.target.value)"><option value="available">Available</option><option value="off_duty">Off duty</option><option value="leave">Leave</option><option value="unavailable">Unavailable</option></select><span v-else class="text-xs text-slate-400">Managed automatically</span></td></tr></tbody></table></div></section></PageShell></template>
<script setup>import{computed,defineComponent,h,onMounted,ref}from'vue';import PageShell from '@/components/management/PageShell.vue';import{fetchOrganizationMembers,updateOrganizationMemberAvailability}from'@/services/organizationManagement';import{useSession}from'@/composables/useSession';import{useToast}from'@/composables/useToast';const{hasPermission}=useSession(),toast=useToast(),members=ref([]),stats=ref({}),loading=ref(false),canUpdate=computed(()=>hasPermission('hr.availability.update')),assignedCount=computed(()=>members.value.filter(x=>x.availability_status==='assigned').length);const Stat=defineComponent({props:{label:String,value:[String,Number]},setup:p=>()=>h('article',{class:'rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm dark:border-white/10 dark:bg-[#071829]'},[h('p',{class:'text-2xl font-black dark:text-white'},String(p.value??0)),h('p',{class:'mt-1 text-xs font-bold text-slate-500'},p.label)])});const pretty=v=>String(v||'').replaceAll('_',' ').replace(/\b\w/g,m=>m.toUpperCase());async function load(){loading.value=true;try{const d=await fetchOrganizationMembers();members.value=d.members||[];stats.value=d.stats||{}}finally{loading.value=false}}async function change(m,status){try{const d=await updateOrganizationMemberAvailability(m.id,status,'Updated from Duty & Availability.');toast.success(d.message);await load()}catch(e){toast.error(e?.response?.data?.message||'Unable to update availability.')}}onMounted(load)</script>
